
// src/hooks/useBeatPreferencesPDFExport.ts
import { useCallback } from "react";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { format } from "date-fns";

interface BeatPreferencePDFData {
  officers: Array<{
    id: string;
    full_name: string;
    badge_number?: string | null;
    rank?: string | null;
    service_credit?: number;
  }>;
  preferences: Array<{
    officer_id: string;
    first_choice?: string;
    second_choice?: string;
    third_choice?: string;
    unavailable_beats?: string[];
    notes?: string;
  }>;
}

interface ExportOptions {
  selectedDate: Date;
  shiftName: string;
  beatData: BeatPreferencePDFData;
  shiftTypes: Array<{ id: string; name: string }>;
  selectedShiftId: string;
}

// Modern color scheme
const COLORS = {
  primary: [41, 128, 185],
  secondary: [52, 152, 219],
  accent: [155, 89, 182],
  success: [39, 174, 96],
  warning: [243, 156, 18],
  danger: [231, 76, 60],
  light: [248, 249, 250],
  dark: [44, 62, 80],
  gray: [108, 117, 125],
  border: [222, 226, 230]
};

// Placeholder logo
const getLogoBase64 = (): string => {
    const departmentLogo = "data:image/png;base64,";
  return departmentLogo;
};


// Helper function to get last name from full name
const getLastName = (fullName: string): string => {
  if (!fullName) return "";
  const parts = fullName.trim().split(/\s+/);
  return parts[parts.length - 1] || "";
};

// Helper function to get rank abbreviation - CHANGED TO "OFC" for officers
const getRankAbbreviation = (rank?: string | null): string => {
  if (!rank) return "OFC";
  
  const rankMap: { [key: string]: string } = {
    'probationary': 'OFC',
    'police officer': 'OFC',
    'police officer ii': 'OFC II',
    'police officer iii': 'OFC III',
    'senior police officer': 'SP/O',
    'corporal': 'Cpl',
    'sergeant': 'Sgt',
    'lieutenant': 'Lt',
    'captain': 'Capt',
    'major': 'Maj',
    'assistant chief': 'A/C',
    'deputy chief': 'D/C',
    'chief': 'Chief'
  };

  const lowerRank = rank.toLowerCase();
  return rankMap[lowerRank] || "OFC";
};

// Draw actual logo function
const drawActualLogo = (pdf: jsPDF, x: number, y: number) => {
  const logoBase64 = getLogoBase64();
  
  if (!logoBase64 || logoBase64 === "placeholder") {
    const logoSize = 20;
    pdf.setFillColor(COLORS.primary[0], COLORS.primary[1], COLORS.primary[2]);
    pdf.rect(x, y, logoSize, logoSize, 'F');
    pdf.setFontSize(6);
    pdf.setTextColor(255, 255, 255);
    pdf.setFont("helvetica", "bold");
    pdf.text("LOGO", x + logoSize/2, y + logoSize/2, { align: 'center', baseline: 'middle' });
    return logoSize;
  }

  try {
    const logoWidth = 20;
    const logoHeight = 20;
    pdf.addImage(logoBase64, 'PNG', x, y, logoWidth, logoHeight);
    return logoWidth;
  } catch (error) {
    console.error('Error drawing logo:', error);
    const logoSize = 20;
    pdf.setFillColor(COLORS.primary[0], COLORS.primary[1], COLORS.primary[2]);
    pdf.rect(x, y, logoSize, logoSize, 'F');
    pdf.setFontSize(6);
    pdf.setTextColor(255, 255, 255);
    pdf.setFont("helvetica", "bold");
    pdf.text("LOGO", x + logoSize/2, y + logoSize/2, { align: 'center', baseline: 'middle' });
    return logoSize;
  }
};

export const useBeatPreferencesPDFExport = () => {
  const exportToPDF = useCallback(async ({ 
    selectedDate, 
    shiftName, 
    beatData, 
    shiftTypes, 
    selectedShiftId 
  }: ExportOptions) => {
    try {
      console.log("Beat Preferences PDF Export - Received data:", { selectedDate, shiftName });

      if (!beatData || !selectedDate) {
        throw new Error("No beat data or date provided for PDF export");
      }

      const pdf = new jsPDF("portrait", "mm", "a4");
      const pageWidth = pdf.internal.pageSize.getWidth();
      const pageHeight = pdf.internal.pageSize.getHeight();

      // Draw logo in top left
      drawActualLogo(pdf, 15, 15);

      // Title
      const currentShift = shiftTypes?.find(s => s.id === selectedShiftId);
      const title = `Beat Preferences - ${currentShift?.name || shiftName || "Shift"}`;
      
      pdf.setFontSize(18);
      pdf.setFont("helvetica", "bold");
      pdf.setTextColor(COLORS.dark[0], COLORS.dark[1], COLORS.dark[2]);
      pdf.text(title, pageWidth / 2, 28, { align: "center" });

      // Generation Date
      pdf.setFontSize(10);
      pdf.setFont("helvetica", "normal");
      pdf.setTextColor(COLORS.gray[0], COLORS.gray[1], COLORS.gray[2]);
      pdf.text(
        `Generated: ${format(new Date(), "MMM d, yyyy h:mm a")}`,
        pageWidth - 15,
        38,
        { align: "right" }
      );

      // Sort Order Note
      pdf.setFontSize(9);
      pdf.setTextColor(COLORS.dark[0], COLORS.dark[1], COLORS.dark[2]);
      pdf.text(
        `Sorted by Seniority (highest to lowest)`,
        15,
        45
      );

      // Prepare table data - REMOVED UNAVAILABLE COLUMN
      const tableData = beatData.officers.map((officer) => {
        const preferences = beatData.preferences.find(p => p.officer_id === officer.id);
        
        return [
          getRankAbbreviation(officer.rank), // Rank - now "OFC" for officers
          getLastName(officer.full_name) || "-",
          officer.badge_number || "-",
          `${officer.service_credit?.toFixed(1) || '0.0'} yrs`, // Seniority
          preferences?.first_choice || "-",
          preferences?.second_choice || "-",
          preferences?.third_choice || "-"
        ];
      });

      // Sort by service credit (highest to lowest)
      const sortedData = [...tableData].sort((a, b) => {
        const aCredit = parseFloat(a[3].replace(' yrs', ''));
        const bCredit = parseFloat(b[3].replace(' yrs', ''));
        return bCredit - aCredit;
      });

      // Create table using autoTable - UPDATED HEADERS (removed "Unavailable")
      autoTable(pdf, {
        head: [["Rank", "Officer", "Badge #", "Seniority", "1st Choice", "2nd Choice", "3rd Choice"]],
        body: sortedData,
        startY: 50,
        margin: { left: 15, right: 15 },
        headStyles: {
          fillColor: [COLORS.primary[0], COLORS.primary[1], COLORS.primary[2]],
          textColor: 255,
          fontStyle: 'bold',
          fontSize: 10,
          cellPadding: 4
        },
        bodyStyles: {
          fontSize: 9,
          textColor: COLORS.dark,
          cellPadding: 3
        },
        alternateRowStyles: {
          fillColor: [COLORS.light[0], COLORS.light[1], COLORS.light[2]]
        },
        styles: {
          cellPadding: 3,
          lineColor: [COLORS.border[0], COLORS.border[1], COLORS.border[2]],
          lineWidth: 0.1,
          overflow: 'linebreak',
          valign: 'middle'
        },
        // UPDATED: Wider column widths for Rank and Seniority
        columnStyles: {
          0: { cellWidth: 20, halign: 'center' },  // Rank - centered and wider
          1: { cellWidth: 28, halign: 'left' },    // Officer
          2: { cellWidth: 22, halign: 'center' },  // Badge # - centered
          3: { cellWidth: 25, halign: 'center' },  // Seniority - centered and wider
          4: { cellWidth: 30, halign: 'center' },  // 1st Choice - centered
          5: { cellWidth: 30, halign: 'center' },  // 2nd Choice - centered
          6: { cellWidth: 30, halign: 'center' }   // 3rd Choice - centered
        },
        didDrawCell: (data) => {
          // Apply color coding to preference columns
          if (data.column.index >= 4 && data.column.index <= 6 && data.cell.raw !== "-") {
            const colors = [
              [0, 100, 0], // Green for 1st choice
              [0, 0, 150], // Blue for 2nd choice
              [128, 0, 128] // Purple for 3rd choice
            ];
            const colorIndex = data.column.index - 4;
            pdf.setTextColor(colors[colorIndex][0], colors[colorIndex][1], colors[colorIndex][2]);
          } else {
            // Default text color for other columns
            pdf.setTextColor(COLORS.dark[0], COLORS.dark[1], COLORS.dark[2]);
          }
        },
        // REMOVED the problematic willDrawCell function entirely
        // The column widths are already wide enough to handle the text
      });

      // Get final Y position after table
      const finalY = (pdf as any).lastAutoTable.finalY || pageHeight - 30;

      // Footer with summary statistics
      const officersWithCompletePrefs = beatData.preferences.filter(p => 
        p.first_choice && p.second_choice && p.third_choice
      ).length;

      pdf.setFontSize(8);
      pdf.setTextColor(COLORS.gray[0], COLORS.gray[1], COLORS.gray[2]);
      pdf.text(
        `Total Officers: ${beatData.officers.length} | Officers with Complete Preferences: ${officersWithCompletePrefs}`,
        pageWidth / 2,
        finalY + 10,
        { align: "center" }
      );

      // Generate filename
      const dateStr = format(selectedDate, "yyyy-MM-dd");
      const dayOfWeek = format(selectedDate, "EEEE").toUpperCase();
      const shiftTypeName = currentShift?.name.replace(/\s+/g, "_") || shiftName.replace(/\s+/g, "_");
      const filename = `Beat_Preferences_${shiftTypeName}_${dayOfWeek}_${dateStr}.pdf`;

      pdf.save(filename);

      return { success: true, filename };
    } catch (error) {
      console.error("Beat Preferences PDF export error:", error);
      return { success: false, error };
    }
  }, []);

  return { exportToPDF };
};
